import sys, heapq
from collections import defaultdict

def bignum(s):
    t=list(map(int,s.split())); m=t[0]; A=t[1:1+m]; n=t[1+m]; B=t[2+m:2+m+n]; k=t[2+m+n]
    def pick(a,c):
        drop=len(a)-c; st=[]
        for x in a:
            while drop and st and st[-1]<x: st.pop(); drop-=1
            st.append(x)
        return st[:c]
    def merge(a,b):
        r=[]
        while a or b:
            if a>b: r.append(a.pop(0))
            else: r.append(b.pop(0))
        return r
    best=[]
    for i in range(max(0,k-n),min(k,m)+1):
        best=max(best,merge(pick(A,i),pick(B,k-i)))
    return " ".join(map(str,best))

print(bignum(sys.stdin.read()))

